// OPC UA subscription 결과 누적 → flush 에서 1초 스냅샷 발사
// 방어 로직: 관리 메시지 / 비정상 상태 / NodeId 아닌 메시지 차단
if (msg.topic === 'subscriptionId') return null;

let sc = msg.StatusCode;
if (sc === undefined && msg.payload && msg.payload.statusCode) {
  sc = msg.payload.statusCode.value;
}
if (sc !== undefined && sc !== 0) return null;
if (!msg.topic || !String(msg.topic).startsWith('ns=')) return null;

const buf = flow.get('opcua_buf_TEST-01') || {};
const raw = String(msg.topic);
const name = raw.replace(/^.*s=/, '');

let v = msg.payload;
if (v && typeof v === 'object') {
  if (v.value && typeof v.value === 'object' && 'value' in v.value) {
    v = v.value.value;
  } else if ('value' in v && !('dataType' in v)) {
    v = v.value;
  }
}

buf[name] = v;
flow.set('opcua_buf_TEST-01', buf);
flow.set('opcua_last_seen_TEST-01', Date.now());
return null;

const EQ = 'TEST-01';
const STATUS_MAP = {0:'IDLE',1:'RUNNING',2:'WARNING',3:'ERROR',4:'COMPLETE'};
const NAMES = ["power", "status", "alarm_active", "alarm_code", "heartbeat", "part_count", "bore_dimension_sp", "hole_dimension_sp", "bore_dimension", "hole_dimension", "progress", "cycle_time"];
const buf = flow.get('opcua_buf_' + EQ) || {};
if (Object.keys(buf).length === 0) return null;
const tags = {};
for (const n of NAMES) { if (n in buf) tags[n] = buf[n]; }
if (Object.keys(tags).length === 0) return null;

const statusCode = ('status' in tags) ? Number(tags.status) : null;
const progress = ('progress' in tags) ? Number(tags.progress) : null;

let resultLatch = context.get('result_ok_latch');
if (resultLatch === undefined || resultLatch === null) resultLatch = true;

if (statusCode === 0) {
  resultLatch = true;
} else if (statusCode === 1 || statusCode === 2) {
  const bore = Number(tags.bore_dimension);
  const hole = Number(tags.hole_dimension);

  const boreValid = Number.isFinite(bore);
  const holeValid = Number.isFinite(hole);
  const progressValid = Number.isFinite(progress) && progress >= 5; // 예: 5% 이후만 판정

  if (boreValid && holeValid && progressValid) {
    const boreOk = bore >= 39.975 && bore <= 40.02;
    const holeOk = hole >= 10.16 && hole <= 10.24;
    if (!(boreOk && holeOk)) resultLatch = false;
  }
}
else if (statusCode === 3){
  resultLatch = false
}

context.set('result_ok_latch', resultLatch);
tags.result_ok = resultLatch;

if ('status' in tags) {
  tags.status_code = tags.status;
  tags.status = STATUS_MAP[tags.status] ?? String(tags.status);
}

const hb = tags.heartbeat ?? null;
if (hb !== null) {
  const lastHb = context.get('last_hb');
  const lastTs = context.get('last_hb_ts') || 0;
  const now = Date.now();
  if (hb !== lastHb) {
    context.set('last_hb', hb);
    context.set('last_hb_ts', now);
  }
  tags.connected = (hb !== lastHb) || (now - lastTs < 3000);
}

const cs = context.get('cyclestate') || {acc:0,lastct:null,startms:null};
const prog = tags.progress ?? null;
if (prog !== null) {
  if (cs.startms === null && prog > 0 && prog < 1.0) cs.startms = Date.now();
  if (cs.startms !== null && prog >= 1.0 && cs.acc < 1.0) {
    cs.lastct = (Date.now() - cs.startms) / 1000;
    cs.startms = null;
  }
  cs.acc = prog;
  context.set('cyclestate', cs);
}
if (cs.lastct !== null && !('cycle_time' in tags)) tags.cycle_time = cs.lastct;
msg.payload = { equipment_id: EQ, tags };
return msg;

