const EQUIP_ID = 'WASH-01';
const TOTAL = 3;

const STATUS_MAP = {
  0: 'IDLE',
  1: 'RUNNING',
  2: 'WARNING',
  3: 'ERROR',
  4: 'COMPLETE'
};

function s16(v) {
  v = (v || 0) & 0xFFFF;
  return (v & 0x8000) ? v - 0x10000 : v;
}

function wordsToFloat(words, wordOffset) {
  const i = wordOffset * 2;
  const buf = Buffer.alloc(4);
  buf.writeUInt16BE((words[i] || 0) & 0xFFFF, 0);
  buf.writeUInt16BE((words[i + 1] || 0) & 0xFFFF, 2);
  return +buf.readFloatBE(0).toFixed(3);
}

const r = Array.isArray(msg.payload)
  ? msg.payload
  : ((msg.responseBuffer && msg.responseBuffer.data) || []);

let buf = context.get('buf') || {};
let count = context.get('count') || 0;

if (msg.topic === 'COILS') {
  buf.power = !!r[0];
  buf.alarm_active = !!r[10];
  count++;

} else if (msg.topic === 'HR_INT') {
  const statusCode = s16(r[4]);
  const hb = s16(r[8]);

  buf.status_code = statusCode;
  buf.status = STATUS_MAP[statusCode] || `UNKNOWN_${statusCode}`;
  buf.alarm_code = s16(r[6]);
  buf.heartbeat = hb;
  buf.part_count = s16(r[10]);
  count++;

} else if (msg.topic === 'HR_FLOAT') {
  buf.cleaning_concentration_sp = wordsToFloat(r, 0);
  buf.cleaning_temperature_sp = wordsToFloat(r, 1);
  buf.cleaning_pressure_sp = wordsToFloat(r, 2);
  buf.cleaning_concentration = wordsToFloat(r, 3);
  buf.cleaning_temperature = wordsToFloat(r, 4);
  buf.cleaning_pressure = wordsToFloat(r, 5);
  buf.progress = wordsToFloat(r, 6);
  buf.cycle_time = wordsToFloat(r, 7);
  count++;
}

context.set('buf', buf);
context.set('count', count);
if (count < TOTAL) return null;

const hb = buf.heartbeat;
const lastHb = context.get('last_hb');
const lastTs = context.get('last_hb_ts') || 0;
const now = Date.now();

if (hb !== undefined && hb !== lastHb) {
  context.set('last_hb', hb);
  context.set('last_hb_ts', now);
}

buf.connected = (hb !== undefined) && ((hb !== lastHb) || (now - lastTs < 3000));

context.set('buf', {});
context.set('count', 0);

msg.payload = {
  equipment_id: EQUIP_ID,
  tags: buf
};
return msg;

