// ── 통합 파서 ──────────────────────────────────────────
// MC Read 4개 결과를 topic으로 구분해 context에 누적,
// 4개 모두 수신되면 하나의 payload로 merge하여 출력.
//
// Read ①  topic="M_BITS"        : M0,11      → power, alarm_active
// Read ②  topic="SP_FLOATS"     : DREAL0,3   → sp 3개 (float)
// Read ③  topic="INTS"          : D10,8      → status, alarm_code, heartbeat, part_count (int)
// Read ④  topic="SENSOR_FLOATS" : DREAL100,5 → sensor 3개+progress+cycle_time (float)
// + heartbeat 기반 connected 계산
// ──────────────────────────────────────────────────────
const EQUIP_ID = "CAST-01";
const TOTAL = 4;

const STATUS_MAP = {
  0: "IDLE",
  1: "RUNNING",
  2: "WARNING",
  3: "ERROR",
  4: "COMPLETE"
};

const topic = msg.topic;
const p = msg.payload;
const arr = Array.isArray(p) ? p : [p];

let buf = context.get('buf') || {};
let count = context.get('count') || 0;

if (topic === 'M_BITS') {
  buf.power = !!arr[0];
  buf.alarm_active = !!arr[10];
  count++;

} else if (topic === 'SP_FLOATS') {
  buf.injection_pressure_sp = +Number(arr[0]).toFixed(3);
  buf.mold_temperature_sp = +Number(arr[1]).toFixed(3);
  buf.cooling_flow_sp = +Number(arr[2]).toFixed(3);
  count++;

} else if (topic === 'INTS') {
  const statusCode = Number(arr[0]);
  const alarmCode = Number(arr[2]);
  const heartbeat = Number(arr[4]);
  const partCount = Number(arr[6]);

  buf.status_code = statusCode;
  buf.status = STATUS_MAP[statusCode] || `UNKNOWN_${statusCode}`;
  buf.alarm_code = alarmCode;
  buf.heartbeat = heartbeat;
  buf.part_count = partCount;
  count++;

} else if (topic === 'SENSOR_FLOATS') {
  buf.injection_pressure = +Number(arr[0]).toFixed(3);
  buf.mold_temperature = +Number(arr[1]).toFixed(3);
  buf.cooling_flow = +Number(arr[2]).toFixed(3);
  buf.progress = +Number(arr[3]).toFixed(3);
  buf.cycle_time = +Number(arr[4]).toFixed(3);
  count++;
}

context.set('buf', buf);
context.set('count', count);

if (count < TOTAL) return null;

const hb = buf.heartbeat;
const lastHb = context.get('last_hb') || null;
const lastTs = context.get('last_hb_ts') || 0;
const now = Date.now();

if (hb !== lastHb) {
  context.set('last_hb', hb);
  context.set('last_hb_ts', now);
}

buf.connected = (hb !== lastHb) || (now - lastTs < 3000);

context.set('buf', {});
context.set('count', 0);

msg.payload = { equipment_id: EQUIP_ID, tags: buf };
return msg;

// UPDATE EQUIPMENT STRUCTS
// parser sends: msg.payload = { equipment_id, tags }
// This node maps tags → EquipmentStruct canonical state.

const EQUIPMENT_META = {
  "CAST-01": { line_id: 2, equipment_id: 101, type: "CAST" },
  "CNC-01":  { line_id: 2, equipment_id: 201, type: "CNC" },
  "CNC-02":  { line_id: 2, equipment_id: 202, type: "CNC" },
  "CNC-03":  { line_id: 2, equipment_id: 203, type: "CNC" },
  "WASH-01": { line_id: 2, equipment_id: 301, type: "WASH" },
  "ASSY-01": { line_id: 2, equipment_id: 401, type: "ASSY" },
  "ASSY-02": { line_id: 2, equipment_id: 402, type: "ASSY" },
  "TEST-01": { line_id: 2, equipment_id: 501, type: "TEST" },
  "TEST-02": { line_id: 2, equipment_id: 502, type: "TEST" }
};

const STATUS_MAP = { 0: 0, 1: 1, 2: 4, 3: 3, 4: 2 };
// legacy: 0=IDLE,1=RUNNING,2=WARNING,3=ERROR,4=COMPLETE
// new:    0=IDLE,1=RUNNING,2=COMPLETED,3=WARNING,4=ERROR
const LEGACY_STR_MAP = { IDLE: 0, RUNNING: 1, WARNING: 3, ERROR: 4, COMPLETE: 2, COMPLETED: 2, UNKNOWN: 0 };
const STALE_MS = 3000;
const UNCERTAIN_MS = 10000;

function toStatusCode(raw) {
  if (raw === null || raw === undefined) return 0;
  if (typeof raw === 'number') return STATUS_MAP[raw] !== undefined ? STATUS_MAP[raw] : 0;
  const s = String(raw).toUpperCase();
  return LEGACY_STR_MAP[s] !== undefined ? LEGACY_STR_MAP[s] : 0;
}

function deriveQualityCode(lastUpdateMs) {
  if (!lastUpdateMs) return 0; // BAD
  const age = Date.now() - lastUpdateMs;
  if (age > UNCERTAIN_MS) return 0; // BAD
  if (age > STALE_MS) return 1;     // UNCERTAIN
  return 2;                          // GOOD
}

const p = msg.payload || {};
const eqName = p.equipment_id;
if (!eqName) return null;

const meta = EQUIPMENT_META[eqName];
if (!meta) return null;

const structs = flow.get('equipment_structs') || {};
const s = structs[eqName] || {
  line_id: meta.line_id, equipment_id: meta.equipment_id,
  ts_epoch_ms: 0, quality_code: 0,
  progress: NaN, cycle_time: NaN,
  power: false, status_code: 0,
  cmd_status: 0, cmd_accepted: 0, cmd_id: 0,
  heartbeat: 0, part_count: 0,
  data_1_setpoint: NaN, data_1_sensor: NaN,
  data_2_setpoint: NaN, data_2_sensor: NaN,
  data_3_setpoint: NaN, data_3_sensor: NaN
};

const tags = p.tags || {};
const now = Date.now();

// Common fields
if ('power' in tags)     s.power      = !!tags.power;
if ('progress' in tags)  s.progress   = Number(tags.progress);
if ('cycletime' in tags) s.cycle_time = Number(tags.cycletime);
if ('cycle_time' in tags) s.cycle_time = Number(tags.cycle_time);
if ('heartbeat' in tags) s.heartbeat  = Number(tags.heartbeat) | 0;
if ('partcount' in tags) s.part_count = Number(tags.partcount) | 0;
if ('part_count' in tags) s.part_count = Number(tags.part_count) | 0;

const rawStatus = tags.status !== undefined ? tags.status : (tags.status_code !== undefined ? tags.status_code : undefined);
if (rawStatus !== undefined) s.status_code = toStatusCode(rawStatus);

// data_1~3 by equipment type
if (meta.type === 'CAST') {
  // data_1=inject_pressure, data_2=spindle_speed(moldtemp), data_3=cooling_flow
  if ('inject_pressure_sp' in tags || 'injection_pressure_sp' in tags)
    s.data_1_setpoint = Number(tags.inject_pressure_sp ?? tags.injection_pressure_sp);
  if ('inject_pressure' in tags || 'injection_pressure' in tags)
    s.data_1_sensor   = Number(tags.inject_pressure ?? tags.injection_pressure);
  if ('mold_temperature_sp' in tags) s.data_2_setpoint = Number(tags.mold_temperature_sp);
  if ('mold_temperature' in tags)    s.data_2_sensor   = Number(tags.mold_temperature);
  if ('cooling_flow_sp' in tags)     s.data_3_setpoint = Number(tags.cooling_flow_sp);
  if ('cooling_flow' in tags)        s.data_3_sensor   = Number(tags.cooling_flow);

} else if (meta.type === 'CNC') {
  // data_1=spindle_speed, data_2=tool_usage, data_3=coolant_flow
  if ('spindlespeedsp' in tags || 'spindle_speed_sp' in tags)
    s.data_1_setpoint = Number(tags.spindlespeedsp ?? tags.spindle_speed_sp);
  if ('spindlespeed' in tags || 'spindle_speed' in tags)
    s.data_1_sensor   = Number(tags.spindlespeed ?? tags.spindle_speed);
  if ('toolusagesp' in tags || 'tool_usage_sp' in tags)
    s.data_2_setpoint = Number(tags.toolusagesp ?? tags.tool_usage_sp);
  if ('toolusage' in tags || 'tool_usage' in tags)
    s.data_2_sensor   = Number(tags.toolusage ?? tags.tool_usage);
  if ('coolantflowsp' in tags || 'coolant_flow_sp' in tags)
    s.data_3_setpoint = Number(tags.coolantflowsp ?? tags.coolant_flow_sp);
  if ('coolantflow' in tags || 'coolant_flow' in tags)
    s.data_3_sensor   = Number(tags.coolantflow ?? tags.coolant_flow);

} else if (meta.type === 'WASH') {
  // data_1=cleaning_concentration, data_2=cleaning_temperature, data_3=cleaning_pressure
  if ('cleaning_concentration_sp' in tags) s.data_1_setpoint = Number(tags.cleaning_concentration_sp);
  if ('cleaning_concentration' in tags)    s.data_1_sensor   = Number(tags.cleaning_concentration);
  if ('cleaning_temperature_sp' in tags)   s.data_2_setpoint = Number(tags.cleaning_temperature_sp);
  if ('cleaning_temperature' in tags)      s.data_2_sensor   = Number(tags.cleaning_temperature);
  if ('cleaning_pressure_sp' in tags)      s.data_3_setpoint = Number(tags.cleaning_pressure_sp);
  if ('cleaning_pressure' in tags)         s.data_3_sensor   = Number(tags.cleaning_pressure);

} else if (meta.type === 'ASSY') {
  // data_1=tightening_torque, data_2=tightening_angle, data_3=press_force
  if ('tighteningtorquesp' in tags || 'tightening_torque_sp' in tags)
    s.data_1_setpoint = Number(tags.tighteningtorquesp ?? tags.tightening_torque_sp);
  if ('tighteningtorque' in tags || 'tightening_torque' in tags)
    s.data_1_sensor   = Number(tags.tighteningtorque ?? tags.tightening_torque);
  if ('tighteninganglesp' in tags || 'tightening_angle_sp' in tags)
    s.data_2_setpoint = Number(tags.tighteninganglesp ?? tags.tightening_angle_sp);
  if ('tighteningangle' in tags || 'tightening_angle' in tags)
    s.data_2_sensor   = Number(tags.tighteningangle ?? tags.tightening_angle);
  if ('pressforcesp' in tags || 'press_force_sp' in tags)
    s.data_3_setpoint = Number(tags.pressforcesp ?? tags.press_force_sp);
  if ('pressforce' in tags || 'press_force' in tags)
    s.data_3_sensor   = Number(tags.pressforce ?? tags.press_force);

} else if (meta.type === 'TEST') {
  // data_1=bore_dimension, data_2=hole_dimension, data_3=result_ok (computed)
  if ('boredimensionsp' in tags || 'bore_dimension_sp' in tags)
    s.data_1_setpoint = Number(tags.boredimensionsp ?? tags.bore_dimension_sp);
  if ('boredimension' in tags || 'bore_dimension' in tags)
    s.data_1_sensor   = Number(tags.boredimension ?? tags.bore_dimension);
  if ('holedimensionsp' in tags || 'hole_dimension_sp' in tags)
    s.data_2_setpoint = Number(tags.holedimensionsp ?? tags.hole_dimension_sp);
  if ('holedimension' in tags || 'hole_dimension' in tags)
    s.data_2_sensor   = Number(tags.holedimension ?? tags.hole_dimension);
  // data_3_setpoint = NaN (no setpoint for result_ok)
  s.data_3_setpoint = NaN;
  // result_ok: computed from bore/hole vs setpoint (±tolerance)
  // If result_ok is already passed from parser (legacy), use it; otherwise compute.
  if ('result_ok' in tags) {
    s.data_3_sensor = tags.result_ok ? 1.0 : 0.0;
  } else {
    const bore = s.data_1_sensor;
    const boreSp = s.data_1_setpoint;
    const hole = s.data_2_sensor;
    const holeSp = s.data_2_setpoint;
    const boreValid = Number.isFinite(bore) && Number.isFinite(boreSp);
    const holeValid = Number.isFinite(hole) && Number.isFinite(holeSp);
    if (!boreValid || !holeValid) {
      // missing sensor data → keep previous result_ok or set 0
      if (!Number.isFinite(s.data_3_sensor)) s.data_3_sensor = 0.0;
    } else {
      // tolerance: bore ±0.025 around 40.0, hole 10.16~10.24
      const BORE_TOL = 0.025;
      const HOLE_MIN = 10.16, HOLE_MAX = 10.24;
      const boreOk = Math.abs(bore - boreSp) <= BORE_TOL;
      const holeOk = hole >= HOLE_MIN && hole <= HOLE_MAX;
      s.data_3_sensor = (boreOk && holeOk) ? 1.0 : 0.0;
    }
  }
}

// Merge command state if present
const cmdState = (flow.get('equipment_command_state') || {})[eqName];
if (cmdState) {
  s.cmd_status   = cmdState.cmd_status;
  s.cmd_accepted = cmdState.cmd_accepted;
  s.cmd_id       = cmdState.cmd_id;
}

// Timestamp & quality
s.ts_epoch_ms  = now;
s.quality_code = deriveQualityCode(now);

structs[eqName] = s;
flow.set('equipment_structs', structs);
return null;

// PUBLISH - OPC UA Server (EquipmentStruct per-equipment JSON string)
// Receives msg.payload = [{ equipment_name, variable_name, json_string }]
// Publishes each as a single String variable on the OPC UA Server.
// Fixed node contract: payload variables must always exist.

const BOOTSTRAP_MS = 10000;
const RETRY_MS = 1200;

const state = flow.get('opcua_state') || {};
const addMsgs = [];
const varList = [];

const startedAt = flow.get('opcua_started_at') || Date.now();
flow.set('opcua_started_at', startedAt);

function ensureMeta(name) {
  if (!state[name] || typeof state[name] !== 'object') {
    state[name] = {
      phase: 'bootstrap',
      firstSeenAt: Date.now(),
      lastAddAt: 0
    };
  } else {
    if (!state[name].phase) state[name].phase = 'bootstrap';
    if (!state[name].firstSeenAt) state[name].firstSeenAt = Date.now();
    if (!state[name].lastAddAt) state[name].lastAddAt = 0;
  }
  return state[name];
}

function queueAddVariable(name, meta) {
  addMsgs.push({
    topic: `ns=2;s=${name};datatype=String`,
    payload: { opcuaCommand: 'addVariable' }
  });
  meta.phase = 'pending';
  meta.lastAddAt = Date.now();
}

function publish(name, value) {
  const meta = ensureMeta(name);
  const now = Date.now();
  const inBootstrapWindow = (now - startedAt) < BOOTSTRAP_MS;

  if (meta.phase === 'bootstrap') {
    queueAddVariable(name, meta);
    return;
  }

  if (meta.phase === 'pending') {
    if (inBootstrapWindow && (now - meta.lastAddAt >= RETRY_MS)) {
      queueAddVariable(name, meta);
      return;
    }

    if (!inBootstrapWindow) {
      meta.phase = 'ready';
    } else {
      return;
    }
  }

  if (meta.phase === 'ready') {
    varList.push({
      messageType: 'Variable',
      namespace: 2,
      variableName: name,
      variableValue: String(value),
      datatype: 'String'
    });
    return;
  }

  queueAddVariable(name, meta);
}

const items = msg.payload || [];
for (const item of items) {
  publish(item.variable_name, item.json_string);
}

flow.set('opcua_state', state);

if (addMsgs.length > 0) {
  for (const m of addMsgs) node.send(m);
}

const delay = addMsgs.length > 0 ? RETRY_MS : 50;
setTimeout(() => {
  if (varList.length > 0) node.send({ payload: varList });
}, delay);

return null;

// BUILD EQUIPMENT JSONS
