const CMD_STATUS_MAP = {
  IDLE: 0, SENDING: 1, COMPLETED: 2, BUSY: 3,
  FAULT: 4, TIMEOUT: 5, REJECTED_INVALID: 6, REJECTED_BUSY: 7,
  UNKNOWN: 0, REJECTEDINVALID: 6, REJECTEDBUSY: 7,
